var H = 32;
var N = 140;
var M = [
  ["#5c280b", "#8c3f14", "#c26224", "#e28d4b", "#f7be83", "#ffe7cc"],
  ["#4d5663", "#727e8f", "#9aa6b8", "#c5cfde", "#e8eef7", "#ffffff"],
  ["#694506", "#9e6c0c", "#d19718", "#f0bf35", "#ffe175", "#fff8cc"]
];
var P = [];
var cache = { bgDark: null, bgLight: null, glow: null, sweep: null };

function mkBackdrop(api, dark) {
  var c = api.h.createCanvas(320, H);
  var g = c.getContext("2d");
  var lg = g.createLinearGradient(0, 0, 320, 0);
  if (dark) {
    lg.addColorStop(0.00, "#3a1909");
    lg.addColorStop(0.32, "#6e3214");
    lg.addColorStop(0.52, "#464f5e");
    lg.addColorStop(0.68, "#6a7484");
    lg.addColorStop(0.84, "#8f620c");
    lg.addColorStop(1.00, "#c89119");
  } else {
    lg.addColorStop(0.00, "#8f451c");
    lg.addColorStop(0.32, "#c46b32");
    lg.addColorStop(0.52, "#788599");
    lg.addColorStop(0.68, "#9ca8ba");
    lg.addColorStop(0.84, "#c28b16");
    lg.addColorStop(1.00, "#e8b32a");
  }
  g.fillStyle = lg;
  g.fillRect(0, 0, 320, H);
  var vg = g.createLinearGradient(0, 0, 0, H);
  vg.addColorStop(0, "rgba(255,255,255,0.22)");
  vg.addColorStop(0.45, "rgba(0,0,0,0)");
  vg.addColorStop(1, "rgba(0,0,0,0.34)");
  g.fillStyle = vg;
  g.fillRect(0, 0, 320, H);
  return c;
}

function mkGlow(api) {
  var c = api.h.createCanvas(64, 64);
  var g = c.getContext("2d");
  var rg = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  rg.addColorStop(0, "rgba(255,248,210,0.95)");
  rg.addColorStop(0.35, "rgba(255,215,110,0.42)");
  rg.addColorStop(1, "rgba(255,200,80,0)");
  g.fillStyle = rg;
  g.fillRect(0, 0, 64, 64);
  return c;
}

function mkSweep(api) {
  var c = api.h.createCanvas(64, 8);
  var g = c.getContext("2d");
  var lg = g.createLinearGradient(0, 0, 64, 0);
  lg.addColorStop(0, "rgba(255,255,255,0)");
  lg.addColorStop(0.45, "rgba(255,252,235,0.75)");
  lg.addColorStop(0.55, "rgba(255,255,255,0.95)");
  lg.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = lg;
  g.fillRect(0, 0, 64, 8);
  return c;
}

return {
  init: function (api) {
    cache.bgDark = mkBackdrop(api, true);
    cache.bgLight = mkBackdrop(api, false);
    cache.glow = mkGlow(api);
    cache.sweep = mkSweep(api);
    P.length = 0;
    var rng = api.h.rand(20261126);
    var i, r1, r2, r3, r4;
    for (i = 0; i < N; i++) {
      r1 = rng();
      r2 = rng();
      r3 = rng();
      r4 = rng();
      P.push({
        u: r1,
        y: 2 + r2 * (H - 4),
        baseY: 2 + r2 * (H - 4),
        spd: 0.06 + r3 * 0.16,
        amp: 1.6 + r4 * 4.0,
        freq: 1.4 + r1 * 2.4,
        phase: r2 * 6.2832,
        r: 1.0 + r4 * 1.9,
        rot: r3 * 6.2832,
        spin: (r1 < 0.5 ? -1 : 1) * (1.4 + r3 * 2.8),
        glintPhase: r4 * 6.2832,
        kickX: 0,
        kickY: 0,
        layer: r3 < 0.35 ? 0 : (r3 < 0.78 ? 1 : 2)
      });
    }
  },

  draw: function (ctx, s) {
    var W = Math.max(40, s.width || 300);
    var E = Math.max(2, Math.min(W, s.end || 0));
    var hi = s.high || 0;
    var mx = s.max || 0;
    var bt = s.burst || 0;
    var dark = s.dark !== false;
    var t = s.time || 0;
    var dtSec = (s.dt || 0) / 60;
    if (dtSec > 0.05) dtSec = 0.05;
    var flowSpd = 0.55 + hi * 0.65 + mx * 0.95 + bt * 1.2;

    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, E, H);
    ctx.clip();

    // 1) 三阶金属光泽基底（铜 -> 银 -> 金）
    ctx.globalAlpha = dark ? 0.92 : 0.96;
    ctx.drawImage(dark ? cache.bgDark : cache.bgLight, 0, 0, W, H);

    // 2) 双层流动沙丘波纹（随 s.time 持续推移）
    var d, x, y, step = 12;
    for (d = 0; d < 2; d++) {
      ctx.beginPath();
      ctx.moveTo(0, H);
      for (x = 0; x <= E + step; x += step) {
        var nx = x / Math.max(1, W);
        var wave = Math.sin(nx * (7.5 + d * 4.5) - t * (1.35 + d * 0.75) + d * 2.1)
                 + Math.cos(nx * 14 - t * 0.9 + d) * 0.35;
        y = H - (7.5 + d * 3.8 + nx * 3.5 + mx * 2.2) + wave * (1.8 + hi * 1.1 + mx * 0.8);
        ctx.lineTo(x, y);
      }
      ctx.lineTo(E + step, H);
      ctx.closePath();
      ctx.globalAlpha = (d === 0 ? 0.24 : 0.16) + mx * 0.10;
      ctx.fillStyle = d === 0 ? (dark ? "rgba(255,220,145,0.55)" : "rgba(255,244,210,0.48)") : "rgba(32,18,6,0.55)";
      ctx.fill();
    }

    // 3) 持续循环流沙粒子（无沉底停死，拖拽速度与指针会扬起金银砂浪）
    var count = Math.min(N, 54 + Math.round(hi * 44 + mx * 42));
    var vel = s.velocity || 0;
    var pi = s.pointer && s.pointer.inside ? s.pointer : null;
    var i, p, px, py, uNorm, mi, si, glint, ca, sa, hw, hv, dx, dy, d2, f;

    for (i = 0; i < count; i++) {
      p = P[i];
      if (dtSec > 0) {
        p.u += (p.spd * flowSpd + vel * 0.08 + p.kickX) * dtSec;
        if (p.u > 1.03) p.u -= 1.06;
        else if (p.u < -0.03) p.u += 1.06;
        p.rot += p.spin * (0.7 + flowSpd * 0.5) * dtSec;
        p.kickX *= Math.pow(0.18, dtSec);
        p.kickY *= Math.pow(0.16, dtSec);
      }
      px = p.u * E;
      py = p.baseY + Math.sin(t * p.freq + p.phase + p.u * 6.2) * p.amp * (0.65 + hi * 0.35 + mx * 0.45) + p.kickY;
      if (pi && dtSec > 0) {
        dx = px - pi.x;
        dy = py - pi.y;
        d2 = dx * dx + dy * dy + 28;
        if (d2 < 900) {
          f = 240 / d2;
          p.kickX += (dx * f * 0.015) * dtSec;
          p.kickY += (dy * f * 0.45) * dtSec;
        }
      }
      if (py < 1.5) py = 1.5;
      else if (py > H - 1.5) py = H - 1.5;

      uNorm = px / Math.max(1, W);
      mi = uNorm < 0.34 ? 0 : (uNorm < 0.68 ? 1 : 2);
      glint = 0.5 + 0.5 * Math.sin(t * (3.2 + p.layer * 1.4) + p.glintPhase);
      si = 2 + (p.layer === 2 ? 1 : 0) + (glint > 0.72 ? 1 : 0) + (mx > 0.4 && glint > 0.85 ? 1 : 0);
      if (si > 5) si = 5;

      ctx.globalAlpha = 0.68 + p.layer * 0.14 + glint * 0.18;
      ctx.fillStyle = M[mi][si];
      ca = Math.cos(p.rot);
      sa = Math.sin(p.rot);
      hw = p.r * (0.9 + mx * 0.3);
      hv = hw * (0.52 + 0.24 * Math.abs(Math.sin(p.rot * 0.7)));
      ctx.beginPath();
      ctx.moveTo(px - hw * ca + hv * sa, py - hw * sa - hv * ca);
      ctx.lineTo(px + hw * ca + hv * sa, py + hw * sa - hv * ca);
      ctx.lineTo(px + hw * ca - hv * sa, py + hw * sa + hv * ca);
      ctx.lineTo(px - hw * ca - hv * sa, py - hw * sa + hv * ca);
      ctx.closePath();
      ctx.fill();

      // 金属晶面瞬闪星芒
      if (glint > 0.84 && p.layer >= 1) {
        ctx.globalAlpha = Math.min(1, (glint - 0.84) * 6.5);
        ctx.fillStyle = M[mi][5];
        var sp = 1.6 + mx * 1.2;
        ctx.fillRect(px - sp, py - 0.4, sp * 2, 0.8);
        ctx.fillRect(px - 0.4, py - sp, 0.8, sp * 2);
      }
    }

    // 4) 丝滑金属斜向扫光（正确使用秒级时钟 t）
    var sweepCycle = (t * 0.42) % 1.45;
    if (sweepCycle < 1.0) {
      var sx = -56 + sweepCycle * (E + 112);
      ctx.save();
      ctx.globalAlpha = (dark ? 0.24 : 0.30) + hi * 0.12 + mx * 0.14;
      ctx.transform(1, 0, -0.35, 1, sx, 0);
      ctx.drawImage(cache.sweep, 0, 0, 52, H);
      ctx.restore();
    }

    // 5) 末端液金辉光（High 起增强）
    if (hi > 0.02 || mx > 0.02) {
      ctx.globalAlpha = Math.min(0.75, 0.22 + hi * 0.22 + mx * 0.32);
      var gw = 28 + hi * 10 + mx * 16;
      ctx.drawImage(cache.glow, E - gw * 0.5, H * 0.5 - gw * 0.5, gw, gw);
    }

    // 6) 主题色微光渗透（正确调用 s.pal.main(alpha) 函数）
    if (s.pal && typeof s.pal.main === "function") {
      ctx.globalAlpha = 1;
      ctx.fillStyle = s.pal.main(dark ? 0.10 : 0.08);
      ctx.fillRect(0, 0, E, H);
      ctx.fillStyle = s.pal.light(0.24 + mx * 0.16);
      ctx.fillRect(0, 0, E, 1.2);
    }

    // 7) Max 入档金属冲击波
    if (bt > 0.02) {
      var rr = 1 - bt;
      ctx.globalAlpha = bt * 0.72;
      ctx.strokeStyle = "#fff5c2";
      ctx.lineWidth = 1.2 + bt * 1.8;
      ctx.beginPath();
      ctx.ellipse(E - 2, H * 0.5, 4 + rr * 36, 3 + rr * 14, 0, 0, 6.2832);
      ctx.stroke();
    }

    ctx.restore();
  }
};
